{
  "measure_id": "MEAS-66497B0C",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Requires every county jail to honor federal immigration detainer requests by holding the specified individuals for up to an additional 48 hours past their normal release time."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§1",
      "concern_id": "C52",
      "effect": "advances",
      "direction": null,
      "quote": "honor a detainer request from federal immigration authorities",
      "mechanism": "Mandates that local county jails participate in federal immigration enforcement by honoring detainer requests.",
      "certainty": "stated"
    },
    {
      "id": "f2",
      "clause_id": "§1",
      "concern_id": "C21",
      "effect": "moves",
      "direction": "shifts authority from local governments to the state",
      "quote": "Every county jail shall honor a detainer request",
      "mechanism": "Replaces county-by-county discretion with a statewide mandate requiring local jails to comply with federal detainers.",
      "certainty": "stated"
    },
    {
      "id": "f3",
      "clause_id": "§1",
      "concern_id": "C46",
      "effect": "advances",
      "direction": null,
      "quote": "holding the named person for up to 48 hours after the person would otherwise be released.",
      "mechanism": "Expands the detention powers of county jails, allowing them to hold individuals beyond their standard release time for immigration purposes.",
      "certainty": "stated"
    },
    {
      "id": "f4",
      "clause_id": "§1",
      "concern_id": "C32",
      "effect": "costs",
      "direction": null,
      "quote": "holding the named person for up to 48 hours after the person would otherwise be released.",
      "mechanism": "Subjecting individuals to continued detention based on an administrative request after the legal justification for their local custody has expired.",
      "certainty": "stated"
    },
    {
      "id": "f5",
      "clause_id": "§1",
      "concern_id": "C53",
      "effect": "costs",
      "direction": null,
      "quote": "Every county jail shall honor a detainer request",
      "mechanism": "Eliminates local policies that protect undocumented immigrants from being transferred to federal custody upon release.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Under current law, each county decides for itself whether its jail will honor federal immigration detainer requests. This measure replaces that local choice with a statewide mandate, requiring all county jails to honor these requests and hold individuals for up to 48 extra hours.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q2",
      "answer": "Direct costs fall on counties, which must pay to house, feed, and supervise individuals for up to 48 additional hours. There are also opportunity costs for jail bed space, and potential legal costs if counties face litigation over the constitutionality of extended holds.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "Federal immigration authorities benefit from the guaranteed window to take individuals into custody without needing to track them down post-release. County governments and local taxpayers bear the financial burden of the extended detention. Immigrants subject to the detainers bear the cost of extended incarceration and subsequent federal custody.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Undocumented immigrants and mixed-status families may avoid interacting with local police or utilizing government services due to fear that any arrest, even for minor offenses, will lead to deportation. Local law enforcement may need to adjust jail operations to accommodate the mandatory holds.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses the issue of federal immigration authorities lacking sufficient time to take custody of individuals being released from local jails, as well as the inconsistency of county-by-county policies. The mechanism—a mandatory 48-hour hold—standardizes the rule and guarantees a time window for federal agents to arrive.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "The state legislature and federal immigration authorities gain power, while county governments and local sheriffs lose the discretion to manage their jails according to local policy preferences.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "The effect of mandatory immigration cooperation on public safety is disputed. Some researchers find that such policies reduce crime by ensuring the removal of individuals who have committed offenses, while others find that they increase crime by chilling community cooperation with law enforcement, making victims and witnesses less likely to report crimes.",
      "disputed": true
    }
  ],
  "flags": [
    {
      "clause_id": "§1",
      "flag_id": "F4",
      "quote": "Every county jail shall honor a detainer request from federal immigration authorities by holding the named person for up to 48 hours",
      "note": "Requires local county jails to hold individuals for extra time without providing state funding to cover the costs of this extended detention."
    }
  ],
